#!/usr/bin/env node
// Packs all version-controlled skills from .agents/skills/ and skills-lock.json
// into src/vendor/bundledSkills.ts for offline Antigravity sandbox extraction.
import { readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { deflateRawSync } from 'node:zlib'

const repoRoot = path.resolve(import.meta.dirname, '..')
const skillsDir = path.join(repoRoot, '.agents', 'skills')
const lockPath = path.join(repoRoot, 'skills-lock.json')
const outPath = path.join(repoRoot, 'src', 'vendor', 'bundledSkills.ts')

function walkSkillFiles(dir, prefix = '') {
  const out = {}
  const entries = readdirSync(dir).sort()
  for (const entry of entries) {
    const full = path.join(dir, entry)
    const rel = prefix ? `${prefix}/${entry}` : entry
    const st = statSync(full)
    if (st.isDirectory()) {
      Object.assign(out, walkSkillFiles(full, rel))
    } else if (st.isFile()) {
      out[rel] = readFileSync(full, 'utf8')
    }
  }
  return out
}

const skillNames = readdirSync(skillsDir)
  .filter((name) => statSync(path.join(skillsDir, name)).isDirectory())
  .sort()

const filesMap = walkSkillFiles(skillsDir)

const lockJson = JSON.parse(readFileSync(lockPath, 'utf8'))
const lockHashes = {}
for (const [name, meta] of Object.entries(lockJson.skills || {}).sort(([a], [b]) =>
  a.localeCompare(b)
)) {
  lockHashes[name] = meta.computedHash
}

const compressedB64 = deflateRawSync(Buffer.from(JSON.stringify(filesMap), 'utf8'), {
  level: 9,
}).toString('base64')

const tsContent = `// AUTO-GENERATED by scripts/sync-skills-bundle.mjs — DO NOT EDIT MANUALLY.
// Contains deterministic deflate-compressed bundle of version-controlled .agents/skills/
// and lockfile hashes from skills-lock.json.

export const BUNDLED_SKILLS_NAMES = ${JSON.stringify(skillNames, null, 2)} as const

export const BUNDLED_SKILLS_LOCK_HASHES: Readonly<Record<string, string>> = ${JSON.stringify(
  lockHashes,
  null,
  2
)}

export const BUNDLED_SKILLS_DEFLATE_B64 = ${JSON.stringify(compressedB64)}
`

writeFileSync(outPath, tsContent, 'utf8')
console.log(
  `Synced ${skillNames.length} skills (${Object.keys(filesMap).length} files, ${
    Object.keys(lockHashes).length
  } lockfile hashes, ${(compressedB64.length / 1024).toFixed(1)} KB base64) -> src/vendor/bundledSkills.ts`
)
